def reset_global_state():
    old_active = stamina.is_active()
    old_testing = stamina.CONFIG.testing
    old_hooks = stamina.get_on_retry_hooks()
    stamina.set_active(True)
    stamina.set_testing(False)
    stamina.set_on_retry_hooks([])
    try:
        yield
    finally:
        stamina.set_active(old_active)
        stamina.CONFIG.testing = old_testing
        stamina.set_on_retry_hooks(old_hooks)


def test_retry_sync_success_after_retry() -> None:
    calls = {"count": 0}

