    def flaky() -> int:
        calls["count"] += 1
        if calls["count"] == 1:
            raise ValueError("boom")
        return 42

    assert flaky() == 42
    assert calls["count"] == 2


def test_retry_sync_with_predicate() -> None:
    calls = {"count": 0}

    def should_retry(exc: Exception) -> bool:
        return isinstance(exc, ValueError)

    @stamina.retry(on=should_retry, attempts=3, wait_max=0)
    def flaky() -> str:
        calls["count"] += 1
        if calls["count"] < 3:
            raise ValueError("boom")
        return "ok"

    assert flaky() == "ok"
    assert calls["count"] == 3


