def test_hook_management_and_context_manager_hooks() -> None:
    events: list[str] = []

    @contextmanager
    def hook_context():
        events.append("enter")
        try:
            yield
        finally:
            events.append("exit")

    def hook(details: RetryDetails):
        events.append(f"retry:{details.retry_num}")
        return hook_context()

    stamina.set_on_retry_hooks([hook])

    calls = {"count": 0}
    for attempt in stamina.retry_context(ValueError, attempts=2, wait_max=0):
        with attempt:
            calls["count"] += 1
            if calls["count"] == 1:
                raise ValueError("boom")

    assert events == ["retry:1", "enter", "exit"]


